{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.spends_growth_scorecard as with cat_spends as ( select date, sum(case when category = \'Shirts\' then spends end)::int as shirts_spends, sum(case when category = \'Trousers\' then spends end)::int as Trousers_spends, sum(case when category = \'T-Shirts\' then spends end)::int as TShirts_spends, sum(case when category = \'Jeans\' then spends end)::int as Jeans_spends, sum(case when category = \'Cargo Pants\' then spends end)::int as Cargo_Pants_spends, sum(spends::int) as cat_spends from snitch_db.maplemonk.category_visibility group by 1 ), campaign_spends as ( SELECT date, sum(case when lower(campaign_name) like \'%video%\' then spend end)::int as videos_spends, sum(case when lower(campaign_name) like \'%catlog%\' then spend end)::int as catalog_spends, sum(case when lower(campaign_name) like \'%product%\' then spend end)::int as product_spends, sum(spend)::int as camp_spends FROM snitch_db.maplemonk.marketing_consolidated_snitch WHERE channel IN (\'Facebook\') group by 1 ), influ_spends as ( SELECT date, ifnull(sum(case when lower(ad_name) like \'%influencer%\' then spend end)::int,0) as influencer_spends, ifnull(sum(case when (ad_name) like \'%PA%\' then spend end)::int,0) as partnership_spends, ifnull(sum(case when (ad_name) like \'%CP%\' then spend end)::int,0) as creator_program_spends, ifnull(sum(case when lower(ad_name) like \'%offer%\' then spend end)::int,0) as offer_spends FROM snitch_db.maplemonk.marketing_consolidated_snitch where channel IN (\'Facebook\') group by 1 ), customer_spend AS ( SELECT TO_DATE(date, \'DD/MM/YYYY\') AS date, REPLACE(new_customer_spend, \',\', \'\')::int AS new_customer_spend, REPLACE(returning_customer_spend, \',\', \'\')::int AS returning_customer_spend FROM snitch_db.maplemonk.GS_GROWTH_SPENDS_SPEND ) select a.*, videos_spends, catalog_spends, product_spends, camp_spends, influencer_spends, partnership_spends, creator_program_spends, offer_spends, new_customer_spend, returning_customer_spend from cat_spends a left join campaign_spends b on a.date = b.date left join influ_spends c on a.date = c.date left join customer_spend d on a.date = d.date ; create or replace table snitch_db.maplemonk.cac_calculation as with main as ( SELECT date, case when lower(channel) like \'%whatsapp%\' then \'Whatsapp\' when lower(channel) like \'%sms%\' then \'SMS\' else channel end AS channel_wise, sum(spend)::int spend FROM maplemonk.marketing_consolidated_snitch group by 1,2 ), repeat_total_spend as ( select date, sum(spend) as total_spend, ifnull(sum(case when channel_wise in (\'Whatsapp\',\'SMS\',\'Push\') then ifnull(spend,0) end),0) as repeat_spend from main where date < current_date group by 1 order by date desc ), customer_segmentation as ( SELECT DATE_TRUNC(\'DAY\', date) AS date, sum(ifnull(Total_Repeat_Customers, 0)) AS Repeat_Customers, sum(ifnull(total_new_customers, 0)) AS New_Customers FROM maplemonk.sales_cost_source_snitch GROUP BY 1 ), repeat_fb_spend as ( select date, returning_customer_spend from snitch_db.maplemonk.spends_growth_scorecard ), loyal_customer_spend as ( select order_timestamp::date as order_date, sum(ifnull(free_gift_discount,0)+ifnull(loyalty_discount,0)) as loyal_repeat_spend from snitch_db.maplemonk.fact_items_snitch WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') and gross_sales != 0 and lower(tags) not like \'%creator%\' and order_status = \'Shopify_Processed\' group by 1 ), repeat_spends as ( select a.date, (a.repeat_spend+b.returning_customer_spend + c.loyal_repeat_spend)::int as total_return_spend, (a.total_spend-(a.repeat_spend+b.returning_customer_spend))::int as total_new_spend from repeat_total_spend a left join repeat_fb_spend b on a.date = b.date left join loyal_customer_spend c on a.date = c.order_date ) select a.*, b.Repeat_Customers, b.New_Customers from repeat_spends a left join customer_segmentation b on a.date = b.date ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            